-- ============================================================================
-- V1.54__seed_qa_home_living.sql
-- ----------------------------------------------------------------------------
-- 迁移目的：为「AI客服学习知识库」(ai_cs_learned_kb) 灌注「家居生活」
--           (home_living) 一级分类下 5 个二级分类的种子 Q&A 数据。
--
-- 数据规模：5 个二级分类 × 30 条 = 150 条高价值 Q&A
--
-- 二级分类清单：
--   1. home_furniture - 家具（沙发/床/衣柜/餐桌/椅子/书桌/茶几）
--   2. home_textile   - 家纺（床品/四件套/被子/枕头/毛巾/窗帘/地毯）
--   3. home_kitchen   - 厨房用品（厨具/锅/碗/刀/砧板/餐具/水壶）
--   4. home_decor     - 装饰摆件（装饰/摆件/挂画/花瓶/相框/香薰）
--   5. home_storage   - 收纳整理（收纳箱/衣架/挂钩/置物架）
--
-- 数据特征：
--   - source_type = 'seed'（种子数据，非对话学习）
--   - review_status = 'approved'（已审核通过，可直接用于检索）
--   - enabled = 1 / vector_indexed = 1 / deleted = 0
--   - learn_batch_id = 'seed-v1.54'（批次标识，便于回溯）
--   - score 范围 70-95，按 Q&A 价值差异化
--   - content_hash = MD5(question + answer)，由 SQL 内联计算，保证唯一性
--
-- 写入策略：
--   通过 JOIN ai_cs_kb_category 按 code 关联 category_id，
--   仅匹配 parent_id IS NOT NULL 的二级分类，避免误绑一级分类。
--
-- 注意事项：
--   - 答复文本中的单引号已用两个单引号转义
--   - 不包含任何手机号、微信号、外链等敏感信息
--   - 本脚本可重复执行（content_hash 唯一约束会阻止重复插入，
--     但建议仅在新建库或首次部署时执行）
-- ============================================================================


-- ============================================================================
-- 1. home_furniture（家具）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.54', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'home_furniture' AS code, '这个沙发几成新？有使用痕迹吗' AS question, '亲，这款沙发大概9成新，自用不到一年~实物比图片还新，扶手和坐垫都没有明显磨损，沙发腿也完好。因为是自家用的，保养得不错，没有宠物抓挠和烟头烫痕。我拍了几个细节图您看下，坐感还跟新的一样弹。因为搬家所以才出，价格很实惠，您看中的话尽快拍下，这种成色的二手沙发很抢手~' AS answer, '沙发,成色,使用痕迹,搬家' AS tags, '沙发成色与使用痕迹说明' AS source_summary, 90 AS score
  UNION ALL SELECT 'home_furniture', '实木床是什么材质的？结实吗', '亲，这款是橡胶木实木床，不是贴皮的哦~主框架和床板都是实木，承重300斤没问题，结实耐用。实木的好处就是没有甲醛味，环保安全，家里有老人小孩也放心。床板是排骨架的，透气性好不会发霉。用了两年多一点变形都没有，您放心使用。实物木纹很自然，比板式的有质感多了，性价比很高~', '实木床,材质,承重,环保', '实木床材质与承重说明', 88
  UNION ALL SELECT 'home_furniture', '衣柜有甲醛味吗？环保吗', '亲，这款衣柜是E1级环保板材的，买回来散味散了三个月才开始用，现在完全没有异味了~家里有宝宝所以当时特意选的环保等级高的，用着放心。板材封边做得很好，不会有甲醛释放的隐患。您拿到后直接就能用，不用再散味。因为搬家才出，用了不到两年，成色很新，价格比新的便宜一半，很划算~', '衣柜,甲醛,环保,板材', '衣柜环保等级与异味说明', 87
  UNION ALL SELECT 'home_furniture', '餐桌尺寸多少？能坐几个人', '亲，这款餐桌是1.4米×0.8米的，配4把椅子刚好，挤一挤坐6个人也没问题~高度75cm是标准餐椅高度，坐起来很舒服。桌面是岩板的，耐刮耐高温，刚烧开的锅直接放都没事。尺寸适合大多数家庭餐厅，您量好自家空间再拍就行。实物比图片有质感，这个价格很值，喜欢就尽快下手~', '餐桌,尺寸,坐几人,岩板', '餐桌尺寸与容量说明', 85
  UNION ALL SELECT 'home_furniture', '这个书桌承重怎么样？放电脑稳吗', '亲，这款书桌是加厚板材的，承重80斤完全没问题，放台式电脑加显示器稳稳的~桌腿是钢架的，不会晃动，写字打字都很稳。桌面尺寸1.2米×0.6米，放电脑还剩不少空间，办公学习都够用。用了大半年，桌面没有划痕，因为换了升降桌才出。这个价格买到钢架书桌很划算，您放心拍~', '书桌,承重,钢架,稳定', '书桌承重与稳定性说明', 84
  UNION ALL SELECT 'home_furniture', '茶几有没有磕碰？划痕明显吗', '亲，这款茶几整体成色8.5成新，桌面有一两处轻微划痕，但不仔细看根本看不出来，我拍特写给您看过了~边角没有磕碰掉漆，结构完好稳固。玻璃是钢化玻璃的，安全耐用。因为换了大茶几所以这款出掉，价格很实在，这种小瑕疵不影响使用，性价比很高。您要是介意完美成色可以再考虑下，不介意的话这个价格很值~', '茶几,磕碰,划痕,钢化玻璃', '茶几瑕疵如实说明', 82
  UNION ALL SELECT 'home_furniture', '沙发能送货上门吗？搬楼要钱吗', '亲，沙发这种大件我这边是发物流的，送到您当地物流点自提~如果您需要送货上门，物流可以加钱安排，具体看您那边楼层和电梯情况，一般有电梯几十块钱就行，没电梯要按楼层加价。建议您拍下后我帮您联系物流询价，您觉得合适再安排发货，不合适可以退款。大件物流比快递慢一些，一般3-5天到，您耐心等下~', '沙发,送货,物流,搬楼', '大件家具物流配送说明', 80
  UNION ALL SELECT 'home_furniture', '床是板式还是实木的？耐用吗', '亲，这款床是板式的，但用的是18mm厚的高密度板，不是那种便宜的薄板，很结实耐用~用了三年床板一根都没断，没有任何异响。板式的好处是性价比高，造型也好看，缺点是没有实木那么有质感。如果您预算有限又想要结实耐用的，这款很合适。搬家所以才出，价格很实在，您看中了就尽快拍下~', '床,板式,耐用,高密度板', '板式床材质与耐用性说明', 83
  UNION ALL SELECT 'home_furniture', '衣柜需要自己安装吗？有说明书吗', '亲，这款衣柜是拆装发货的，需要自己安装~发货会带详细的安装说明书和所有配件，按图纸来一般两个人一两小时就能装好。如果您不太会装，也可以找当地的安装师傅，费用大概100-150块。拆装设计的好处是搬家方便带走，比整体衣柜灵活。我当初就是自己装的，不难，您拿到后有问题随时问我~', '衣柜,安装,说明书,拆装', '衣柜安装方式与说明', 79
  UNION ALL SELECT 'home_furniture', '餐桌为什么出？搬家还是换新', '亲，是因为换新了才出的~家里重新装修换了大理石餐桌，这款岩板的就用不上了。餐桌本身成色很好，用了不到一年，桌面没有划痕因为我一直铺着桌布。原价两千多买的，现在出价格很划算。岩板桌面耐刮耐高温很实用，您要是看中了别犹豫，这种成色的二手餐桌很受欢迎，晚了可能就被别人拍走了~', '餐桌,换新,成色,岩板', '出物原因与成色说明', 86
  UNION ALL SELECT 'home_furniture', '这个椅子转椅还能升降吗？气压杆漏气吗', '亲，这款转椅升降功能正常的，气压杆没有漏气，我每天都还在用~坐上去往下压不会沉，升降很顺滑。气压杆是SGS认证的，安全没问题。轮子也顺滑，没卡顿。因为换了人体工学椅才出这款，成色8成新，扶手有点使用痕迹但不影响使用。办公椅这个价格很实惠，您看中了就拍下吧~', '转椅,升降,气压杆,办公椅', '转椅升降功能与气压杆说明', 83
  UNION ALL SELECT 'home_furniture', '书桌尺寸多大？小户型放得下吗', '亲，这款书桌是1米×0.5米的，小巧省空间，小户型完全放得下~放笔记本加鼠标还有富余空间，写字也够用。如果是放台式机加显示器可能会挤一点，您量下自家空间。桌子是白橡木色的，百搭各种装修风格，小户型放卧室角落很合适。用了大半年成色很新，搬家才出，价格比新的便宜一半，很值~', '书桌,尺寸,小户型,省空间', '书桌尺寸与小户型适用性', 82
  UNION ALL SELECT 'home_furniture', '沙发套可拆洗吗？脏了好打理吗', '亲，这款沙发套是可拆洗的，拉链设计，拆下来套洗衣机洗就行，很方便~面料是科技布的，防泼水防污，平时不小心洒了东西擦一下就行，不会渗透进去。用了快一年洗过一次，洗完没有变形缩水，颜色也没褪。科技布比布艺好打理，比真皮便宜，性价比很高。您放心买，打理起来不费事~', '沙发,可拆洗,科技布,打理', '沙发套拆洗与打理说明', 86
  UNION ALL SELECT 'home_furniture', '床的承重多少？胖点的人能睡吗', '亲，这款床承重400斤没问题，排骨架是加厚的，间距小不会塌~我180斤睡两年了一点不塌，结实得很。床板是12根加厚排骨架，比普通的密，支撑力更强。胖一点完全不用担心，放心睡。床是2米×1.8米的，个子高的人也够睡。搬家才出，成色9成新，价格很实惠，看中了就尽快拍下~', '床,承重,排骨架,结实', '床承重与排骨架说明', 84
  UNION ALL SELECT 'home_furniture', '衣柜门是推拉还是平开？滑轮顺滑吗', '亲，这款衣柜是推拉门的，滑轮很顺滑，推起来没有卡顿~推拉门的好处是省空间，床边放衣柜也不怕门打不开。滑轮用了两年没坏，静音效果也不错。门板是百叶设计的，透气好看。衣柜深度55cm，能挂大衣。搬家才出，成色8.5成新，推拉门滑轮完好，这个价格很值，您看中了就拍下~', '衣柜,推拉门,滑轮,省空间', '衣柜门类型与滑轮说明', 83
  UNION ALL SELECT 'home_furniture', '茶几玻璃是钢化的吗？安全吗', '亲，这款茶几玻璃是3C认证的钢化玻璃，安全没问题~钢化玻璃比普通玻璃结实5倍，万一碎裂也是钝角小颗粒不会伤人。厚度12mm，放重物稳稳的，我家茶几上常年放水果盘和茶具都没事。边角做了圆角处理，家里有小孩也不怕磕碰。用了两年多完好无损，搬家才出，价格很实在，您放心拍~', '茶几,钢化玻璃,安全,3C', '茶几钢化玻璃安全性说明', 85
  UNION ALL SELECT 'home_furniture', '这个鞋柜几层？能放多少双鞋', '亲，这款鞋柜是4层的，每层能放3-4双，总共能放12-16双鞋~如果是高跟鞋或靴子可能会少放几双。鞋柜是翻斗设计的，开门一翻就能拿鞋，省空间又方便。高度1米左右，顶部还能放钥匙包之类的小物件。玄关放一个很实用，用了大半年成色很新，换了大鞋柜才出，价格很实惠，您看中了就拍下~', '鞋柜,层数,容量,翻斗', '鞋柜容量与设计说明', 82
  UNION ALL SELECT 'home_furniture', '沙发有塌陷吗？坐感还弹吗', '亲，这款沙发没有塌陷，坐感还很弹~填充的是高密度海绵加羽绒，坐下去软弹有支撑，站起来马上回弹，没有那种坐久了凹下去回不来的情况。用了不到一年，海绵没老化，坐感跟新的差不多。我是搬家才出的，平时很爱惜，没在上面蹦跳过。这个成色和价格很值，您看中了就尽快拍下，好的二手沙发很抢手~', '沙发,塌陷,回弹,海绵', '沙发塌陷与坐感说明', 87
  UNION ALL SELECT 'home_furniture', '床垫一起出吗？还是要单买', '亲，床垫和床是分开的，您可以选择只买床或者床+床垫一起~床垫是独立袋装弹簧的，软硬适中，用了不到一年成色很新，一直铺着床单所以很干净。单买床是标价，加床垫加200就行，比单买划算很多。如果只要床也可以，床垫我再单独出。您看怎么合适，拍下后告诉我一声就行~', '床垫,单买,配套,独立弹簧', '床垫配套购买说明', 84
  UNION ALL SELECT 'home_furniture', '衣柜是组装的还是整装的？搬家方便拆吗', '亲，这款衣柜是拆装式的，搬家很方便拆~用的三合一连接件，拆下来打好包就能带走，到新家再装回去就行。比整体衣柜灵活多了，整体衣柜搬家基本就废了。拆装不复杂，两个人一个多小时能搞定。我这次就是拆下来准备搬走，结果新家风格不搭才出的，配件说明书都在，您拿到后有问题随时问我~', '衣柜,拆装,搬家,三合一', '衣柜拆装与搬家便利性', 80
  UNION ALL SELECT 'home_furniture', '餐桌可折叠吗？平时不用省空间', '亲，这款餐桌是可折叠的，展开1.4米吃饭用，折叠后0.7米靠墙放省空间~小户型特别实用，平时折叠起来当边桌，来客了展开坐4-6个人吃饭。折叠铰链是金属的，用了两年没有松动，展开很稳不会晃。桌面是岩板的不怕烫。这种折叠餐桌市面上不便宜，我搬家才出，价格很实惠，您看中了就拍下~', '餐桌,折叠,省空间,小户型', '折叠餐桌省空间说明', 86
  UNION ALL SELECT 'home_furniture', '这个斗柜有几个抽屉？抽拉顺滑吗', '亲，这款斗柜是5抽屉的，抽拉很顺滑，用了三轨金属滑轨~每个抽屉深度18cm，能放不少东西，内衣袜子、杂物化妆品都能收纳。滑轨用了两年没坏，抽拉没有卡顿，静音顺滑。柜子是白橡木色的，百搭好看。高80cm放床头当床头柜也合适。搬家才出，成色8.5成新，价格很实在，您看中了就尽快拍下~', '斗柜,抽屉,滑轨,收纳', '斗柜抽屉与滑轨说明', 83
  UNION ALL SELECT 'home_furniture', '书架层板能调节吗？放书会弯吗', '亲，这款书架层板是可以调节的，每层有多个卡位，按书本高度自由调节~层板是加厚的18mm板材，放满书不会弯，我之前放了三层书一点变形都没有。书架是5层的，高度1.8米，收纳量很大。背板有防倒孔，可以固定在墙上更安全。搬家才出，成色很新，这个价格很值，您看中了就拍下~', '书架,层板,调节,承重', '书架层板调节与承重说明', 84
  UNION ALL SELECT 'home_furniture', '沙发颜色实物有色差吗？耐脏吗', '亲，沙发是深灰色的，实物比图片稍微深一点点，但基本没色差~深灰色很耐脏，平时有点灰看不太出来，这点很适合懒人。科技布面料防泼水，不小心洒了东西擦一下就行。我家是自用，没有小孩画笔之类的痕迹。深灰色百搭各种装修风格，不会过时。您要是担心色差我可以拍自然光下的实物图给您看，看完再决定~', '沙发,色差,耐脏,深灰', '沙发颜色与耐脏说明', 82
  UNION ALL SELECT 'home_furniture', '床头有储物格吗？带不带插座', '亲，这款床床头是带储物格的，可以放手机眼镜书本，很方便~但没有自带插座，床头后面留了穿线孔，您可以把插线板从孔里穿过来，充电很方便。储物格是翻盖设计的，关上就是平的，好看不积灰。床是软包床头的，靠上去看手机很舒服。用了不到一年成色很新，搬家才出，价格很实惠，您看中了就拍下~', '床,床头,储物格,穿线孔', '床头储物与穿线设计', 81
  UNION ALL SELECT 'home_furniture', '衣柜深度多少？能挂大衣吗', '亲，这款衣柜深度55cm，挂大衣完全没问题~一般大衣挂上去门也能正常关上，55cm是标准衣柜深度，挂衣够用。衣柜内部是上面挂衣杆下面抽屉的设计，挂衣区高度1.2米，长款大衣也能挂。抽屉可以放叠好的衣物。用了两年成色8.5成新，搬家才出，价格很实在，您看中了就拍下~', '衣柜,深度,挂大衣,挂衣杆', '衣柜深度与挂衣说明', 83
  UNION ALL SELECT 'home_furniture', '餐桌椅一起带吗？还是单出桌子', '亲，餐桌和椅子是分开的，您可以选只要桌子或者桌椅一起~单买餐桌是标价，加4把椅子加200，一套买更划算。椅子是实木的，坐感结实，用了不到一年没有松动。原价一套三千多，现在出价格很实惠。如果只要桌子我也可以单出，椅子另外挂。您看怎么合适拍下后告诉我一声就行~', '餐桌,椅子,配套,分开买', '餐桌椅配套购买说明', 82
  UNION ALL SELECT 'home_furniture', '这个梳妆台镜子清晰吗？带灯吗', '亲，这款梳妆台镜子是高清银镜的，成像很清晰不变形~镜子不带灯，但镜框周围留了装灯带的槽，您想加灯带可以自己装一个，几十块钱很方便。梳妆台带3个抽屉，化妆品护肤品都能收纳。桌面是白色的，显得干净。用了大半年成色很新，换了大梳妆台才出，价格很实惠，您看中了就拍下~', '梳妆台,镜子,高清,抽屉', '梳妆台镜子与收纳说明', 81
  UNION ALL SELECT 'home_furniture', '书桌带抽屉吗？收纳够用吗', '亲，这款书桌带2个抽屉的，收纳日常文具文件够用~抽屉是三轨滑轨，抽拉顺滑静音。抽屉深度足够放A4文件和笔记本。桌面1.2米宽，放电脑加抽屉还有不少操作空间。如果您东西特别多可能不够，可以配个桌边收纳架。用了大半年成色很新，换了升降桌才出，价格很实在，您看中了就拍下~', '书桌,抽屉,收纳,滑轨', '书桌抽屉与收纳说明', 82
  UNION ALL SELECT 'home_furniture', '沙发出自无烟无宠物家庭吗？有味道吗', '亲，沙发出自无烟无宠物家庭，非常干净~我家没人抽烟也没有养宠物，沙发没有烟味和宠物毛，也没有螨虫异味。用之前一直铺着沙发垫，面料保护得很好。您收到后可以直接用，不需要特别清洗除味。我家装修搬新家才出的，成色9成新，这个价格很值，您看中了就尽快拍下，好的成色不多见~', '沙发,无烟,无宠物,干净', '沙发来源与卫生说明', 91
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 2. home_textile（家纺）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.54', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'home_textile' AS code, '四件套是什么面料的？会起球吗' AS question, '亲，这款四件套是100%全棉的，60支贡缎面料，手感丝滑不起球~全棉的好处是透气吸汗，一年四季都能用。60支算是高支棉了，比市面上40支的密度更高，更柔软耐用，洗了不会起球也不会缩水变形。我用了半年洗过几次还跟新的一样，因为换季换风格才出的。全棉四件套这个价格很实惠，您放心拍~' AS answer, '四件套,全棉,起球,60支' AS tags, '四件套面料与起球说明' AS source_summary, 88 AS score
  UNION ALL SELECT 'home_textile', '被子几斤的？冬天盖暖和吗', '亲，这款被子是4斤的蚕丝被，冬天有暖气的话盖着刚好，没暖气建议搭配一条毛毯~蚕丝被的好处是轻盈贴身，盖着不压人，保暖性比棉被好。如果您那边冬天比较冷，建议选6斤的，我可以给您看看6斤的款。4斤适合春秋和有暖气的冬天。被子用了大半年成色很新，换了大被子才出，价格很实惠~', '被子,蚕丝,保暖,几斤', '被子重量与保暖性说明', 85
  UNION ALL SELECT 'home_textile', '枕头多高？软的还是硬的', '亲，这款枕头高度10cm，软硬适中偏软~记忆棉材质，睡上去会慢慢贴合颈椎，有支撑但不硬。适合侧睡和仰睡都行。如果您喜欢高枕或者硬枕，这款可能不太合适，我也有乳胶枕的款可以给您推荐。用了大半年成色很新，一直套着枕套所以很干净。换枕头才出的，价格很实惠，您看中了就拍下~', '枕头,高度,记忆棉,软硬', '枕头高度与软硬度说明', 83
  UNION ALL SELECT 'home_textile', '这套床品洗了会缩水吗', '亲，这款四件套是全棉预缩处理的，洗了基本不会缩水~我洗过三四次，尺寸没变化，也没变形起球。建议用冷水洗，不要用热水和强力甩干，这样面料寿命更长。全棉的东西多少会有点缩，但预缩处理过的缩水率在3%以内，几乎感觉不到。您放心洗，正常机洗就行。用了半年成色很新，价格很实惠~', '床品,缩水,全棉,预缩', '床品缩水与洗涤说明', 84
  UNION ALL SELECT 'home_textile', '窗帘遮光怎么样？能挡住阳光吗', '亲，这款窗帘是遮光率90%的，白天拉上房间也很暗，午睡完全没问题~面料是加厚遮光布的，背面有涂层，不是那种薄薄的只遮一层。卧室用特别合适，周末睡懒觉不会被阳光晒醒。客厅用也行，看电视不反光。用了不到一年成色很新，搬家才出。如果您要100%全黑可以选择双层遮光款，我给您发链接看看~', '窗帘,遮光,涂层,卧室', '窗帘遮光率说明', 86
  UNION ALL SELECT 'home_textile', '地毯防滑吗？下面要不要垫', '亲，这款地毯背面是防滑点胶的，直接铺在瓷砖木地板上都不会滑~只要地面干净平整就不需要额外加防滑垫。如果是太光滑的大理石地面，建议加个防滑垫更稳妥。地毯是短绒的，不掉毛好打理，吸尘器一吸就干净。用了大半年成色很新，换风格才出，价格比新的便宜不少，您看中了就拍下~', '地毯,防滑,点胶,短绒', '地毯防滑与打理说明', 83
  UNION ALL SELECT 'home_textile', '四件套是全棉的还是混纺的', '亲，这款四件套是100%全棉的，不是混纺~您可以看水洗标，成分写着100%棉。全棉比混纺透气吸汗，贴身用更舒服，缺点是容易皱。混纺虽然不起皱但透气性差，贴身用闷。这款是60支全棉贡缎，比普通全棉更丝滑，不容易起皱。用了半年成色很新，换季换风格才出，全棉四件套这个价格很实惠，您放心拍~', '四件套,全棉,混纺,成分', '四件套面料成分说明', 85
  UNION ALL SELECT 'home_textile', '被子是被芯还是被套？都能洗吗', '亲，这款是被芯，不能整条水洗，只能局部擦拭或晒太阳~蚕丝被芯水洗会结块报废的，建议套着被套用，脏了洗被套就行。被芯定期晒一晒杀菌除螨就好，不要大力揉搓。如果您要可水洗的，我可以给您推荐棉纤被芯，那个可以机洗。蚕丝被的好处是轻盈保暖，但打理要注意。用了大半年成色很新，价格很实惠~', '被子,被芯,水洗,蚕丝', '被芯洗涤注意事项', 82
  UNION ALL SELECT 'home_textile', '枕头用久了会塌吗？回弹怎么样', '亲，这款记忆棉枕头回弹很好，用了大半年没有塌~记忆棉的好处就是慢回弹，睡下去贴合颈椎，起来慢慢恢复原状，不会像普通海绵枕用久了就扁了。正常用2-3年回弹都没问题。建议不要长期重压，不用的时候平放就行。我换了乳胶枕才出的，枕头成色很新，价格很实惠，您看中了就拍下~', '枕头,回弹,记忆棉,塌陷', '枕头回弹与耐用说明', 84
  UNION ALL SELECT 'home_textile', '毛巾掉毛吗？吸水好不好', '亲，这款毛巾是新疆长绒棉的，不掉毛吸水好~新毛巾前两次洗可能会有轻微浮毛，这是正常的，洗过几次就不会了。长绒棉纤维长，不容易断，所以不掉毛。吸水性很好，沾水就湿，擦一下就干。克重120g比普通毛巾厚实，用着舒服。用了几次成色很新，买多了才出，价格很实惠，您看中了就拍下~', '毛巾,掉毛,吸水,长绒棉', '毛巾掉毛与吸水说明', 83
  UNION ALL SELECT 'home_textile', '这套床品有色差吗？实物颜色准吗', '亲，这套四件套实物是雾霾蓝，跟图片基本一致，可能有轻微色差但不明显~我拍的是室内自然光，没加滤镜，您看到的颜色比较接近实物。不同手机屏幕显示会有差异，如果您对颜色很敏感，我可以多拍几张不同光线下的给您看。雾霾蓝很显高级，百搭各种卧室风格。用了半年成色很新，价格很实惠，您看中了就拍下~', '床品,色差,实物,雾霾蓝', '床品色差与实物颜色说明', 81
  UNION ALL SELECT 'home_textile', '被子有异味吗？新的是不是要洗', '亲，这款被子是蚕丝的，没有异味，只有淡淡的蚕丝天然味道，通风晾一下就没了~蚕丝被不需要洗，新收到晒一晒通风散散味就行。如果是过敏体质，可以套上被套再用更安心。我家自用的，保养得不错，没有发霉受潮。用了大半年成色很新，换了大被子才出，价格很实惠，您看中了就拍下~', '被子,异味,蚕丝,晾晒', '被子异味与处理说明', 82
  UNION ALL SELECT 'home_textile', '枕头适合颈椎不好的人吗', '亲，这款记忆棉枕对颈椎有一定支撑，比普通棉花枕好~记忆棉会贴合颈椎曲线，分散压力，颈椎不好的人用比软塌的枕头舒服。但如果您颈椎问题比较严重，建议选专门的颈椎枕或者乳胶枕，支撑力更强。我可以给您推荐乳胶枕的款。用了大半年成色很新，换枕头才出，价格很实惠，您看中了就拍下~', '枕头,颈椎,记忆棉,支撑', '枕头颈椎适用性说明', 84
  UNION ALL SELECT 'home_textile', '窗帘尺寸多少？我家窗户能挂吗', '亲，这款窗帘是2米高×2米宽的，适合1.5-1.8米宽的窗户~如果您家窗户尺寸不一样，我可以帮您看看有没有合适的尺寸。窗帘是打孔款的，需要配罗马杆。挂钩款的我也有，您要哪种告诉我。用了不到一年成色很新，搬家才出，价格很实惠。您量好自家窗户和杆子高度再拍就行~', '窗帘,尺寸,打孔,罗马杆', '窗帘尺寸与安装说明', 80
  UNION ALL SELECT 'home_textile', '地毯好清洗吗？能机洗吗', '亲，这款地毯是短绒化纤的，不能整机洗，但很好打理~平时用吸尘器吸一吸就行，有污渍用湿布擦一下就好。短绒的好处是不藏灰不掉毛，比长绒好打理。如果不小心洒了东西，局部清洁剂喷一下擦掉就行。不建议整机洗，容易变形。用了大半年成色很新，换风格才出，价格很实惠，您看中了就拍下~', '地毯,清洗,短绒,打理', '地毯清洗与打理说明', 82
  UNION ALL SELECT 'home_textile', '四件套多少支的？手感怎么样', '亲，这款四件套是60支贡缎的，手感丝滑柔软~60支算是高支高密了，比市面上常见的40支密度更高，更细腻柔软，摸起来像丝绸一样滑。贡缎织法让面料有光泽感，铺在床上显高级。用了半年洗过几次还跟新的一样，不起球不缩水。换季换风格才出，60支全棉这个价格很实惠，您放心拍~', '四件套,60支,贡缎,手感', '四件套支数与手感说明', 86
  UNION ALL SELECT 'home_textile', '被子是蚕丝的还是棉的？哪个暖', '亲，这款是蚕丝被，同等重量下蚕丝比棉暖~蚕丝被轻盈贴身，盖着不压人，保暖性是棉被的1.5倍左右。缺点是价格贵且不能水洗。棉被厚重但便宜可水洗。如果您怕冷又怕重，选蚕丝被；如果预算有限又想要可水洗的，选棉被。这款蚕丝被用了大半年成色很新，价格比新的便宜不少，您看中了就拍下~', '被子,蚕丝,棉,保暖', '蚕丝被与棉被对比', 85
  UNION ALL SELECT 'home_textile', '这条毛毯起静电吗？冬天用', '亲，这款毛毯是法兰绒的，冬天用会有轻微静电，但不严重~法兰绒比珊瑚绒柔软，保暖性好，缺点是化纤材质容易起静电。减少静电的小窍门：洗的时候加柔顺剂，或者房间里放个加湿器。如果您特别怕静电，可以选全棉毛毯，但保暖性会差一些。用了大半年成色很新，换季才出，价格很实惠~', '毛毯,静电,法兰绒,冬天', '毛毯静电与材质说明', 80
  UNION ALL SELECT 'home_textile', '床笠还是床单？床垫多厚能用', '亲，这款是床笠款的，四周有松紧可以包裹床垫~适合15-25cm厚的床垫，市面上大部分床垫都能用。床笠比床单的好处是不会跑偏，睡一晚上起来还是整整齐齐的。如果您家床垫特别厚或者特别薄，告诉我厚度我帮您确认能不能用。用了大半年成色很新，换风格才出，价格很实惠，您看中了就拍下~', '床笠,床垫,松紧,厚度', '床笠适用床垫说明', 82
  UNION ALL SELECT 'home_textile', '枕套几个？四件套都含什么', '亲，标准四件套含1个被套、1个床单（或床笠）、2个枕套~这款就是标准配置，2个枕套。如果您是1.5米的床，四件套是1.5米规格的；1.8米的床对应1.8米规格。拍的时候选对床的尺寸就行。用了半年成色很新，换季换风格才出，全棉60支四件套这个价格很实惠，您放心拍下，有任何问题随时找我~', '四件套,枕套,配置,尺寸', '四件套配置说明', 83
  UNION ALL SELECT 'home_textile', '窗帘带遮光层吗？还是单层', '亲，这款窗帘是双层一体的，面料本身就有遮光涂层，不是单层薄布~遮光率90%，白天拉上房间很暗。背面是银灰遮光涂层，正面是绒布质感，好看又遮光。不需要额外加遮光里衬，一条就够用了。用了不到一年成色很新，搬家才出，价格很实惠。如果您要100%全黑我可以给您推荐加厚款~', '窗帘,遮光,双层,涂层', '窗帘遮光层说明', 84
  UNION ALL SELECT 'home_textile', '地毯掉毛严重吗？刚买会掉吗', '亲，这款短绒地毯基本不掉毛~新收到前两次吸尘可能会有极少浮毛，这是正常的，吸过几次就完全没有了。短绒比长绒掉毛少很多，也不容易藏灰。如果您怕掉毛，选短绒准没错。用了大半年成色很新，吸尘器打理很方便，换风格才出，价格很实惠。您看中了就拍下，有问题随时找我~', '地毯,掉毛,短绒,浮毛', '地毯掉毛说明', 81
  UNION ALL SELECT 'home_textile', '四件套买回来要先洗吗？有甲醛吗', '亲，新四件套建议先洗一遍再用~虽然面料本身甲醛达标，但生产过程中会有浮色和浆料，洗一遍更干净卫生，也能让面料更柔软。用冷水轻柔模式洗，不要漂白。第一次洗可能有轻微浮色，这是全棉的正常现象，洗过就不会了。这款是正规厂家的，有检测报告，甲醛达标放心用。用了半年成色很新，价格很实惠~', '四件套,甲醛,洗涤,新买', '四件套甲醛与首洗说明', 85
  UNION ALL SELECT 'home_textile', '被子夏天盖会不会热？有薄款吗', '亲，这款4斤蚕丝被夏天盖会热，适合春秋和有暖气的冬天~夏天建议用夏凉被或者1-2斤的薄被，我店里有薄款可以给您推荐。蚕丝被的好处是四季都能用，只是重量不同。您如果一年四季都想用蚕丝被，可以备两条不同重量的换着盖。用了大半年成色很新，换了大被子才出，价格很实惠~', '被子,夏天,薄款,夏凉被', '被子季节与薄款说明', 82
  UNION ALL SELECT 'home_textile', '枕头能水洗吗？洗了会结块吗', '亲，这款记忆棉枕不能水洗，水洗会破坏记忆棉结构导致结块~清洁方式是套枕套用，枕套脏了洗枕套就行。枕芯如果不小心弄脏，用湿布局部擦拭然后通风晾干，不要大力揉搓也不要暴晒。定期晒一晒杀菌除螨就好。用了大半年成色很新，一直套着枕套很干净，换枕头才出，价格很实惠，您看中了就拍下~', '枕头,水洗,结块,记忆棉', '枕头洗涤注意事项', 80
  UNION ALL SELECT 'home_textile', '这套是母婴可用的吗？A类吗', '亲，这款四件套是B类的，不是A类~A类是婴幼儿标准，B类是成人直接接触皮肤标准，也是很安全的。如果是给宝宝用，建议选A类标准的，我店里有A类全棉四件套可以给您推荐。成人用B类完全没问题，甲醛和色牢度都达标。用了半年成色很新，价格很实惠，您看是用给谁，我帮您推荐合适的~', '四件套,A类,B类,母婴', '四件套安全等级说明', 86
  UNION ALL SELECT 'home_textile', '窗帘挂钩还是打孔？配件带吗', '亲，这款窗帘是打孔款的，孔径4cm适合25mm以下的罗马杆~罗马杆需要您自己配，窗帘不含杆子。如果您家是滑轨的，我也有挂钩款可以给您换。打孔款的好处是拉动顺滑不打褶，挂钩款可以调节褶皱密度。您告诉我家里是杆还是轨道，我帮您发对的款。用了不到一年成色很新，搬家才出，价格很实惠~', '窗帘,打孔,挂钩,罗马杆', '窗帘安装方式与配件', 81
  UNION ALL SELECT 'home_textile', '地毯尺寸多少？客厅放多大合适', '亲，这款地毯是1.6米×2.3米的，适合客厅茶几下面~一般客厅地毯比茶几大一圈就行，1.6×2.3是客厅常用尺寸。如果茶几小可以选1.4×2米的，茶几大可以选2×3米的。卧室床边的话建议1.6×2.3或者更大。您量好自家空间再拍，用了大半年成色很新，换风格才出，价格很实惠~', '地毯,尺寸,客厅,茶几', '地毯尺寸与选择建议', 82
  UNION ALL SELECT 'home_textile', '床品褪色吗？深色的会不会染衣服', '亲，这款四件套是活性印染的，色牢度高，正常洗不会褪色~第一次洗可能有轻微浮色，这是正常的，洗过就不会了。深色床品第一次建议单独洗，不要跟浅色衣服一起，避免浮色染色。活性印染比涂料印染更环保，颜色更牢固。用了半年洗过几次没有褪色，成色很新，价格很实惠，您放心拍下~', '床品,褪色,印染,色牢度', '床品褪色与印染说明', 84
  UNION ALL SELECT 'home_textile', '被子填充物是什么？结块吗', '亲，这款蚕丝被填充物是100%桑蚕丝长丝绵，不会结块~长丝绵比短丝绵好，韧性足不易断，用久了也不结块。蚕丝被保养得当用5-10年没问题。建议定期晾晒，不要重压，存放时不要抽真空（会压断蚕丝纤维）。用了大半年成色很新，没有结块，换了大被子才出，价格很实惠，您看中了就拍下~', '被子,填充,蚕丝,结块', '被子填充物与结块说明', 85
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 3. home_kitchen（厨房用品）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.54', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'home_kitchen' AS code, '这个锅是不锈钢的吗？会不会生锈' AS question, '亲，这款锅是304食品级不锈钢的，正常使用不会生锈~304不锈钢是食品级的，耐腐蚀耐高温，比201不锈钢好很多。用完擦干水分就不会有水渍锈斑。不要长期放酸性咸的食物过夜就行。用了大半年亮闪闪的没有锈迹，成色很新。买多了用不上才出，价格很实惠，您看中了就拍下~' AS answer, '锅,不锈钢,304,生锈' AS tags, '锅不锈钢材质与防锈说明' AS source_summary, 87 AS score
  UNION ALL SELECT 'home_kitchen', '陶瓷碗能放微波炉吗？安全吗', '亲，这款陶瓷碗是可以放微波炉的，但金边款不建议~纯白无金属边的可以微波，金边银边的不行，金属会打火花。您拍的时候选纯白款就放心微波。这款是高温瓷的，耐高温不掉色。烤箱也能用。但不要从冰箱拿出来直接进微波炉，温差太大会裂。用了大半年成色很新，换风格才出，价格很实惠~', '陶瓷碗,微波炉,金边,高温瓷', '陶瓷碗微波安全性说明', 85
  UNION ALL SELECT 'home_kitchen', '刀具是几件的？锋利吗', '亲，这套刀具是5件的：切片刀、砍骨刀、水果刀、厨房剪、磨刀棒~刀是50Cr15MoV不锈钢的，硬度高锋利耐用，切肉切菜很顺手。砍骨刀能砍鸡骨排骨，但不能砍太硬的牛腿骨。用了大半年切东西还很锋利，磨刀棒偶尔磨一下就行。成色很新，换了一套才出，价格比单买便宜很多，您看中了就拍下~', '刀具,套装,锋利,不锈钢', '刀具套装与锋利度说明', 86
  UNION ALL SELECT 'home_kitchen', '砧板是竹的还是塑料的？发霉吗', '亲，这款砧板是整竹的，比胶合竹板不容易发霉~整竹砧板密度高不易吸水，用完洗净竖起来晾干就不会发霉。比塑料砧板环保，比木头砧板轻。建议生熟分开用两块，我店里有大小两个尺寸可以配着用。用了大半年没有发霉和刀痕深的情况，成色很新。换了大砧板才出，价格很实惠~', '砧板,竹,发霉,整竹', '砧板材质与防霉说明', 84
  UNION ALL SELECT 'home_kitchen', '这个水壶容量多少？烧水快吗', '亲，这款水壶容量1.7L，烧开一壶水大概4-5分钟~功率1800W，比普通水壶快不少。一次烧够泡3-4杯茶或者够一家人喝水。壶身是304不锈钢的，烧水没有异味。有防干烧保护，水烧干了会自动断电，安全。用了大半年成色很新，换了即热式才出，价格很实惠，您看中了就拍下~', '水壶,容量,烧水,防干烧', '水壶容量与烧水速度说明', 83
  UNION ALL SELECT 'home_kitchen', '锅有涂层吗？掉涂层有害吗', '亲，这款是麦饭石不粘锅，有涂层的~涂层是安全的，符合食品级标准，正常使用不会掉。但要注意：不要用铁铲，要用硅胶铲或木铲；不要空锅干烧；洗的时候不要用钢丝球。涂层掉了少量不影响健康，但建议更换。我用木铲用了大半年涂层还完好，成色很新，换了大锅才出，价格很实惠~', '锅,涂层,不粘,麦饭石', '锅涂层与使用注意说明', 86
  UNION ALL SELECT 'home_kitchen', '餐具一套几个？够几个人用', '亲，这套餐具是16件的：4个饭碗、4个菜盘、4个汤碗、4个小碟~够4个人用餐，一家三口完全够用。陶瓷材质高温烧制，微波炉和洗碗机都能用。花色是北欧风的，好看百搭。用了大半年成色很新没有缺口，换了大套才出，价格比单买便宜很多，您看中了就拍下，有问题随时找我~', '餐具,套件,16件,陶瓷', '餐具套件与容量说明', 84
  UNION ALL SELECT 'home_kitchen', '这口炒锅电磁炉能用吗', '亲，这款炒锅是复合底的，电磁炉和燃气灶都能用~锅底是304不锈钢加铝复合导磁底，电磁炉上加热没问题。如果是纯铝锅或者纯不锈钢没复合底的就不能用电磁炉。这款复合底导热均匀，不糊底。用了大半年成色很新，换了大锅才出，价格很实惠。您家里是电磁炉还是燃气灶？我帮您确认下合适不~', '炒锅,电磁炉,复合底,导磁', '炒锅电磁炉适用性说明', 85
  UNION ALL SELECT 'home_kitchen', '刀会生锈吗？怎么保养', '亲，这款刀是不锈钢的，正常使用不会生锈，但要注意保养~用完洗净擦干，不要泡水里过夜。切完咸的酸的食物尽快洗，不要长时间残留。如果长期不用，可以抹一层食用油防锈。不锈钢不是绝对不锈，保养得当才能一直亮闪闪。用了大半年没有锈迹，成色很新，换了一套才出，价格很实惠~', '刀,生锈,保养,不锈钢', '刀具防锈与保养说明', 83
  UNION ALL SELECT 'home_kitchen', '砧板有刀痕吗？使用痕迹明显吗', '亲，这款砧板用了大半年，正面有一些刀痕但不是很深，属于正常使用痕迹~整竹砧板比胶合的耐切，不会掉渣。我拍了刀痕的特写给您看过了，不影响使用。背面是没怎么用的，几乎全新。您如果介意可以翻过来用背面。成色8成新，换了大砧板才出，价格很实惠，这种使用痕迹很正常，性价比高~', '砧板,刀痕,使用痕迹,整竹', '砧板刀痕如实说明', 80
  UNION ALL SELECT 'home_kitchen', '水壶是食品级材质吗？烧水有味吗', '亲，这款水壶壶身是304食品级不锈钢的，内胆直接接触水的也是304，烧水没有异味~第一次用建议先烧两壶水倒掉，清洗一下内胆。304不锈钢是食品级的，耐高温耐腐蚀，烧水不会有金属味。有3C认证，安全放心。用了大半年烧水还是没异味，成色很新，换了即热式才出，价格很实惠~', '水壶,食品级,304,异味', '水壶材质与异味说明', 85
  UNION ALL SELECT 'home_kitchen', '这个锅是几成新？用过几次', '亲，这款锅用了大概十几次，9成新~因为买了之后发现太大了一直没怎么用，基本是新的。锅底有轻微加热痕迹，但涂层完好，没有划痕。我一直用木铲，没有金属铲划伤。原价三百多买的，现在出价格很划算。如果您想要几乎全新的这款很合适，看中了就尽快拍下，晚了可能就没了~', '锅,成色,几次,9成新', '锅成色与使用次数说明', 88
  UNION ALL SELECT 'home_kitchen', '陶瓷碗会烫手吗？盛热汤', '亲，这款陶瓷碗是双层加厚的，盛热汤不会太烫手~但如果是单层薄碗，盛热汤确实会烫。这款碗壁比较厚，隔热性比薄碗好很多，端起来不烫手。但刚从微波炉拿出来还是建议用隔热手套，毕竟陶瓷导热。用了大半年没有裂纹，成色很新，换风格才出，价格很实惠，您看中了就拍下~', '陶瓷碗,烫手,双层,热汤', '陶瓷碗隔热与烫手说明', 82
  UNION ALL SELECT 'home_kitchen', '刀具带刀架吗？收纳方便吗', '亲，这套刀具是带刀架的，收纳很方便~刀架是亚克力通透的，插取方便，也好清洗。5把刀加剪刀都有专属卡位，不会乱。刀架底部有沥水孔，不容易积水发霉。放在台面上也好看。用了大半年成色很新，换了一套才出，价格很实惠。如果您只要刀不要架我也可以单出，您看怎么方便~', '刀具,刀架,收纳,亚克力', '刀具刀架与收纳说明', 83
  UNION ALL SELECT 'home_kitchen', '砧板多大尺寸？切菜够用吗', '亲，这款砧板是38×26cm的，厚度1.5cm，日常切菜够用~如果切整鸡整鱼可能会觉得小，建议选更大的。这款适合小家庭日常用，切水果切菜都很方便。整竹的轻便好拿，女生单手也能端起来。用了大半年成色很新，换了大砧板才出，价格很实惠。您量好自家厨房空间再拍就行~', '砧板,尺寸,切菜,整竹', '砧板尺寸与适用说明', 81
  UNION ALL SELECT 'home_kitchen', '这个汤锅容量多少？够几个人喝汤', '亲，这款汤锅容量4L，够4-6个人喝汤~煮一锅鸡汤够一家人吃。锅是304不锈钢的，导热快省燃气。锅盖是钢化玻璃的，能看到里面不用掀盖。两个侧耳把手端起来不烫。用了大半年成色很新，换了大汤锅才出，价格很实惠。如果您家人口多建议选5L以上的，我帮您推荐~', '汤锅,容量,不锈钢,几人', '汤锅容量与适用人数', 82
  UNION ALL SELECT 'home_kitchen', '锅底厚吗？会不会糊底', '亲，这款锅是复合厚底的，不容易糊底~锅底比锅壁厚，导热均匀，食物受热一致就不会局部糊。便宜的薄底锅容易糊底，这款不会。不粘涂层也有防糊作用。用中小火就行，不要一直大火。用了大半年没有糊底情况，成色很新，换了大锅才出，价格很实惠，您看中了就拍下~', '锅,锅底,糊底,复合底', '锅底厚度与防糊说明', 84
  UNION ALL SELECT 'home_kitchen', '不粘锅能用铁铲吗？要换硅胶铲吗', '亲，不粘锅不能用铁铲，会划伤涂层~建议用硅胶铲、木铲或者竹铲，柔软不伤涂层。铁铲和钢丝球是不粘锅的克星，用几次涂层就花了。我送您一把硅胶铲吧，用着方便。用了大半年我一直用木铲，涂层完好。成色很新，换了大锅才出，价格很实惠。记得不要空锅干烧，也不要骤冷骤热~', '不粘锅,铁铲,硅胶铲,涂层', '不粘锅锅铲使用注意', 86
  UNION ALL SELECT 'home_kitchen', '餐具 microwave safe 吗？能加热吗', '亲，这套餐具纯白无金属边的可以放微波炉，安全~但金边银边款不能微波，金属会打火花。如果您经常微波加热，建议拍纯白款。这套是高温瓷的，耐高温不掉色。烤箱也能用。但不要从冰箱直接进微波炉，温差太大会裂。用了大半年成色很新，换了大套才出，价格很实惠，您看中了就拍下~', '餐具,微波,加热,高温瓷', '餐具微波安全性说明', 83
  UNION ALL SELECT 'home_kitchen', '这套刀是什么钢的？持久锋利吗', '亲，这套刀是50Cr15MoV不锈钢的，含碳量高硬度足，持久锋利~这种钢是中高端刀具常用的，硬度HRC55左右，比普通不锈钢锋利耐用。正常用半年到一年磨一次就行。比几十块的普通不锈钢刀好用很多。用了大半年切东西还很利，成色很新，换了一套才出，价格比专柜便宜很多，您看中了就拍下~', '刀具,钢,锋利,50Cr15', '刀具钢材与锋利度说明', 87
  UNION ALL SELECT 'home_kitchen', '砧板双面用的吗？生熟分开吗', '亲，这款砧板是双面可用的，建议生熟分开~一面切生肉生鱼，另一面切熟食水果，这样更卫生。两面都是整竹的，不掉渣。建议用不同的刀或者做好标记区分正反面。用了大半年我一直生熟分开用，成色很新没有串味。换了大砧板才出，价格很实惠。生熟分开是厨房卫生的基本功，您注意下~', '砧板,双面,生熟分开,卫生', '砧板双面与生熟分开', 84
  UNION ALL SELECT 'home_kitchen', '水壶保温吗？还是只烧水', '亲，这款是电热水壶，只烧水不保温~烧开后自动断电，水会慢慢凉。如果您要保温的，建议买电热水瓶或者保温壶，烧开后能保持温度。这款胜在烧水快，4-5分钟烧开。如果您既要烧水又要保温，我可以给您推荐保温电水壶。用了大半年成色很新，换了即热式才出，价格很实惠~', '水壶,保温,烧水,电热水壶', '水壶功能与保温说明', 80
  UNION ALL SELECT 'home_kitchen', '这个平底锅煎东西粘吗？好用吗', '亲，这款平底锅是不粘涂层的，煎蛋煎鱼都不粘~我用它煎蛋不用放油都不粘，很好用。煎鱼皮也不会粘掉。涂层是麦饭石的，比普通不粘涂层耐磨。注意用木铲硅胶铲，不要空烧，涂层能用很久。28cm适合2-3人份量。用了大半年成色很新，换了大锅才出，价格很实惠，您看中了就拍下~', '平底锅,不粘,煎,麦饭石', '平底锅不粘与使用说明', 86
  UNION ALL SELECT 'home_kitchen', '陶瓷碗有瑕疵吗？金边掉吗', '亲，这套陶瓷碗我仔细检查过没有瑕疵，没有缺口和裂纹~金边是电镀的，正常洗不会掉，但不要用钢丝球擦，也不要长期泡水。洗碗机清洗没问题的。用了大半年金边完好没掉色，成色很新。换了大套才出，价格很实惠。陶瓷的东西发货我会包得严严实实，碎了包赔，您放心拍~', '陶瓷碗,瑕疵,金边,掉色', '陶瓷碗瑕疵与金边说明', 82
  UNION ALL SELECT 'home_kitchen', '锅把手会烫吗？防烫吗', '亲，这款锅把手是电木防烫的，正常炒菜不烫手~电木材质隔热性好，比不锈钢把手好。但如果是长时间炖煮，把手会有点温热，建议用隔热手套更稳妥。把手铆钉加固的，不会松动。用了大半年把手完好，成色很新，换了大锅才出，价格很实惠。您放心用，注意不要明火烧到把手就行~', '锅,把手,防烫,电木', '锅把手防烫说明', 81
  UNION ALL SELECT 'home_kitchen', '这套餐具 dishwasher 安全吗？能机洗吗', '亲，这套陶瓷餐具是可以放洗碗机的，机洗没问题~高温瓷耐高温，洗碗机的温度不会损伤。但金边银边款建议手洗，机洗久了金边可能会淡。纯白款随便机洗。用了大半年我机洗过很多次，完好如新。成色很新，换了大套才出，价格很实惠。如果您要机洗建议选纯白款，更省心~', '餐具,洗碗机,机洗,陶瓷', '餐具洗碗机安全性说明', 83
  UNION ALL SELECT 'home_kitchen', '刀具为什么出？换新还是用不上', '亲，是因为换了一套更好的才出的~这套刀本身很好用，锋利度够，用着顺手。但因为家里来客人多，5件套不够用，换了一套7件套的。这套用了大半年成色很新，刀刃没有崩口，磨刀棒也没怎么用。原价四百多，现在出价格很划算。好刀一副能用很多年，您看中了就尽快拍下~', '刀具,换新,原因,成色', '刀具出物原因说明', 85
  UNION ALL SELECT 'home_kitchen', '砧板有抗菌吗？卫生吗', '亲，整竹砧板本身就有一定的天然抗菌性~竹子含有竹醌成分，能抑制细菌滋生。比木头砧板更不容易发霉。但不管什么砧板，用完都要洗净晾干，定期用盐水或白醋消毒。不要一直湿着放，那样什么砧板都会发霉。用了大半年没有发霉，成色很新，换了大砧板才出，价格很实惠~', '砧板,抗菌,卫生,竹醌', '砧板抗菌与卫生说明', 82
  UNION ALL SELECT 'home_kitchen', '水壶材质是 304 还是 316？哪个好', '亲，这款水壶是304的，316比304耐腐蚀性更好，但日常烧水304完全够用~316多用于医疗和海边高盐环境，烧水用304性价比更高。两种都是食品级不锈钢，安全。316的价格贵30%左右，烧水用没必要。这款304的用了大半年没异味没锈迹，成色很新，换了即热式才出，价格很实惠~', '水壶,304,316,不锈钢', '水壶304与316对比', 85
  UNION ALL SELECT 'home_kitchen', '这个高压锅安全吗？用了几年了', '亲，这款高压锅用了不到两年，安全阀和密封圈都正常~高压锅的核心安全件是限压阀和安全阀，我检查过都通畅没堵。密封圈没有老化变形，合盖严密。建议密封圈每两年换一次，几十块钱。这款是燃气用的，不能电磁炉。用了不到两年成色8成新，换了大高压锅才出，价格很实惠，您放心用~', '高压锅,安全,密封圈,安全阀', '高压锅安全与使用说明', 84
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 4. home_decor（装饰摆件）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.54', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'home_decor' AS code, '这个花瓶是陶瓷的吗？易碎吗' AS question, '亲，这款花瓶是高温陶瓷的，比普通陶瓷结实，但毕竟是陶瓷还是要轻拿轻放~正常摆放不会碎，就是别摔别磕。瓶壁有一定厚度不是那种薄胎瓷，没那么脆。我发货会用气泡膜加泡沫箱包得严严实实，碎了我包赔您放心。用了大半年成色很新没有磕碰，换风格才出，价格很实惠~' AS answer, '花瓶,陶瓷,易碎,包装' AS tags, '花瓶陶瓷材质与包装说明' AS source_summary, 85 AS score
  UNION ALL SELECT 'home_decor', '挂画尺寸多少？适合多大墙面', '亲，这款挂画是50×70cm的，适合1-1.5米宽的墙面~卧室床头、客厅沙发背景墙都合适。如果您家墙面大，可以选两三幅组合挂更有层次。画是油画布的，带实木画框，质感不错。用了大半年成色很新，换风格才出，价格很实惠。您量好自家墙面再拍就行，太小的墙面挂这幅会显得挤~', '挂画,尺寸,墙面,画框', '挂画尺寸与墙面适配', 83
  UNION ALL SELECT 'home_decor', '香薰持久吗？能燃多久', '亲，这款香薰蜡烛100g，能燃25-30小时~每次建议燃2-3小时，让表面充分融化这样不会坑洼。不要燃超过4小时，会冒黑烟。熄灭时用灭烛盖或者灭烛钩，不要吹，吹会冒烟。一瓶能用一个月左右（每天点1小时）。用了几次成色很新，朋友送了新的才出，价格比专柜便宜不少，您看中了就拍下~', '香薰,蜡烛,燃烧,持久', '香薰蜡烛燃烧时长说明', 84
  UNION ALL SELECT 'home_decor', '摆件是什么材质的？有分量吗', '亲，这款摆件是树脂的，有一定分量但不重~树脂摆件的好处是造型精致细节好，比石膏结实比陶瓷轻。底部有毛毡垫，放桌上不划桌面。高度25cm，放书架或者玄关都合适。用了大半年成色很新没有掉漆，换风格才出，价格很实惠。树脂摆件不怕摔不怕磕，家里有小孩也放心~', '摆件,树脂,分量,材质', '摆件材质与分量说明', 82
  UNION ALL SELECT 'home_decor', '相框是木的还是塑料的？质感怎么样', '亲，这款相框是实木的，不是塑料的~实木相框质感比塑料好很多，有木纹自然感，上漆均匀。背面有支架可以桌面摆放，也有挂钩可以挂墙。能放5寸照片。用了大半年成色很新没有划痕，换了大相框才出，价格很实惠。实木相框放家里显档次，您看中了就拍下~', '相框,实木,质感,摆放', '相框材质与质感说明', 81
  UNION ALL SELECT 'home_decor', '这个干花会掉色吗？能放多久', '亲，这款干花是经过固色处理的，正常摆放1-2年不会明显掉色~但不要暴晒，阳光直射会加速褪色。放在阴凉通风处能放更久。干花不用浇水不用打理，省心好看。如果积灰了用吹风机冷风吹一下就行。用了大半年颜色还很好，换风格才出，价格很实惠。您看中了就拍下，干花比鲜花省心多了~', '干花,掉色,固色,摆放', '干花掉色与保养说明', 83
  UNION ALL SELECT 'home_decor', '花瓶能插真花吗？装水会漏吗', '亲，这款花瓶是陶瓷实心的，装水不会漏~可以插真花，瓶口直径8cm，插5-7支花合适。瓶身是不透水的，放桌上不会渗水印。换水的时候倒掉旧水冲洗一下就行。也可以插干花或者仿真花，不用换水更省心。用了大半年成色很新没有裂纹，换风格才出，价格很实惠，您看中了就拍下~', '花瓶,真花,装水,不漏', '花瓶插花与防水说明', 84
  UNION ALL SELECT 'home_decor', '挂画是手绘还是印刷的？有艺术感吗', '亲，这款挂画是高清微喷的，不是手绘的~微喷是博物馆级复制技术，色彩还原度高，比普通印刷细腻很多，质感接近原作。手绘的价格要贵好几倍，这款性价比高。画布是油画布的，有纹理感，远看跟手绘差不多。配了实木画框，挂上去有艺术感。用了大半年成色很新，换风格才出，价格很实惠~', '挂画,微喷,印刷,艺术', '挂画工艺与艺术感说明', 82
  UNION ALL SELECT 'home_decor', '香薰味道浓吗？会不会刺鼻', '亲，这款香薰味道是淡香型，不刺鼻~我选的是白茶味，清淡优雅不冲鼻，适合不喜欢浓香的人。如果是喜欢浓香的，可以选檀香或者麝香款。香薰点燃后整个房间淡淡香味，不会太冲。孕妇和婴幼儿建议不要用香薰，这款也不例外。用了几次成色很新，朋友送了新的才出，价格很实惠~', '香薰,味道,刺鼻,白茶', '香薰味道浓淡说明', 83
  UNION ALL SELECT 'home_decor', '摆件有瑕疵吗？磕碰痕迹明显吗', '亲，这款摆件我仔细检查过没有瑕疵，没有磕碰和掉漆~用了大半年一直摆在柜子里没动过，保存得很好。树脂材质不怕磕不怕摔，没有损伤。我拍了多角度实物图您看过了，成色9成新。换风格才出，价格很实惠。摆件发货我会包严实，运输途中不会有损伤，您放心拍下~', '摆件,瑕疵,磕碰,掉漆', '摆件瑕疵如实说明', 86
  UNION ALL SELECT 'home_decor', '相框能挂墙吗？带挂钩吗', '亲，这款相框既能挂墙也能桌面摆放，背面有挂钩和支架~挂钩是锯齿挂的，挂在墙上一颗钉子就行，比较稳。支架是折叠的，放桌面也很稳。可以放5寸照片。用了大半年成色很新没有划痕，换了大相框才出，价格很实惠。如果您要多幅组合挂墙，我店里有同款多个，可以一起拍~', '相框,挂墙,挂钩,支架', '相框挂墙与摆放说明', 81
  UNION ALL SELECT 'home_decor', '这个摆件几成新？有灰尘使用痕吗', '亲，这款摆件9成新，一直摆在玻璃柜里，没有灰尘使用痕迹~我每周都会擦，保存得很好。树脂材质不变色不老化，摆了半年还跟新的一样。没有掉漆磕碰。换风格才出，价格很实惠。您拿到手擦一下就能摆，跟新的没区别。这种成色的二手摆件性价比很高，您看中了就尽快拍下~', '摆件,成色,灰尘,9成新', '摆件成色与使用痕迹', 88
  UNION ALL SELECT 'home_decor', '花瓶多大？插几支花合适', '亲，这款花瓶高20cm，瓶口直径8cm，插5-7支花合适~如果是大朵花比如芍药，3-5支就够了；小朵花比如满天星，可以插多一些。高度20cm放茶几餐桌都合适，不会太高挡视线。用了大半年成色很新，换风格才出，价格很实惠。您看中了就拍下，插花我也可以给您一些建议~', '花瓶,尺寸,插花,几支', '花瓶尺寸与插花建议', 82
  UNION ALL SELECT 'home_decor', '挂画框是实木的吗？变形吗', '亲，这款挂画画框是实木的，经过烘干处理不会变形~实木画框比PS画框有质感，也不容易变形。背面有背板防尘，画布不会积灰。用了大半年没有变形，南方潮湿天气也没事。成色很新，换风格才出，价格很实惠。挂画发货我会加固包装，画框不会压坏，您放心拍下~', '挂画,画框,实木,变形', '挂画框材质与变形说明', 83
  UNION ALL SELECT 'home_decor', '香薰是植物精油吗？孕妇能用吗', '亲，这款香薰是植物精油调配的，但孕妇不建议使用~虽然成分天然，但精油中的某些成分可能影响孕期。为了安全，孕期和哺乳期最好不要用任何香薰，包括所谓的"孕妇可用"款。这款用了几次成色很新，朋友送了新的才出，价格很实惠。非孕期用这款没问题，味道清淡不刺鼻~', '香薰,精油,孕妇,安全', '香薰精油与孕妇注意', 86
  UNION ALL SELECT 'home_decor', '摆件风格是北欧还是中式？百搭吗', '亲，这款摆件是北欧极简风的，很百搭~造型是几何抽象的，不挑装修风格，现代简约、北欧、日式都能搭。如果家里是中式古典风可能不太搭，建议选中式摆件。北欧风的好处是不容易过时，简约耐看。用了大半年成色很新，换风格才出，价格很实惠。您家里什么风格？我帮您看看搭不搭~', '摆件,北欧,风格,百搭', '摆件风格与搭配说明', 82
  UNION ALL SELECT 'home_decor', '相片墙一套几个？配件带吗', '亲，这套照片墙是5个相框组合，大小不一更有层次~配件都带的：挂钩、无痕钉、水平仪都有，您自己就能装。相框是PS材质的，轻便好挂墙，不用担心承重。能放5寸和6寸照片。用了大半年成色很新，换风格才出，价格很实惠。挂在沙发背景墙或者楼梯间都好看，您看中了就拍下~', '相片墙,组合,配件,相框', '相片墙套件与配件说明', 83
  UNION ALL SELECT 'home_decor', '这个陶瓷摆件手工的吗？独一无二吗', '亲，这款陶瓷摆件是手工拉坯的，每一件都有细微差异，算半独一无二~手工的比注浆的有灵气，不会千篇一律。但因为是手工的，表面可能有些许不规则，这不是瑕疵是手工的特色。用了大半年成色很新，换风格才出，价格比新的便宜不少。手工陶瓷摆件有收藏价值，您看中了就拍下~', '陶瓷,手工,独一无二,拉坯', '陶瓷摆件手工与特色', 85
  UNION ALL SELECT 'home_decor', '花瓶颜色实物准吗？有色差吗', '亲，这款花瓶实物是豆沙绿色的，跟图片基本一致~我拍的是自然光，没加滤镜，颜色比较准。不同手机屏幕会有轻微差异，如果您对颜色很敏感我可以多拍几张不同光线的给您看。豆沙绿很高级百搭，不会太跳。用了大半年成色很新，换风格才出，价格很实惠。您看中了就拍下~', '花瓶,色差,颜色,豆沙绿', '花瓶颜色与色差说明', 80
  UNION ALL SELECT 'home_decor', '挂画防水吗？卫生间能挂吗', '亲，这款挂画不防水，不建议挂卫生间~卫生间湿度大，画布会受潮发霉，画框也会变形。如果是干湿分离的卫生间而且通风好，勉强可以但不建议。这款适合挂客厅卧室书房。卫生间建议选防水材质的装饰画，比如亚克力或者玻璃的。用了大半年成色很新，换风格才出，价格很实惠~', '挂画,防水,卫生间,防潮', '挂画防水与适用场景', 82
  UNION ALL SELECT 'home_decor', '香薰瓶好看吗？不点也能当摆件吗', '亲，这款香薰瓶是磨砂玻璃的，设计简约好看，不点也能当摆件~瓶身有木质盖子，放在桌上很有氛围感。不点的时候盖着盖子，香味不会散失太快。很多买家买回去就是冲着瓶子好看，蜡烛用完了瓶子还能当收纳罐。用了几次成色很新，朋友送了新的才出，价格很实惠，您看中了就拍下~', '香薰,瓶,摆件,磨砂', '香薰瓶摆件与美观说明', 83
  UNION ALL SELECT 'home_decor', '摆件放哪合适？有什么风水讲究吗', '亲，这款摆件放玄关、书架、电视柜都合适~从美观角度，放在视线平齐的位置最好看，不要太低。从风水角度，不同摆件有不同讲究，但这款是中性装饰摆件，没有特殊风水禁忌。一般不建议摆件正对大门，也不要放在横梁下。用了大半年成色很新，换风格才出，价格很实惠，您看中了就拍下~', '摆件,摆放,风水,位置', '摆件摆放与风水建议', 80
  UNION ALL SELECT 'home_decor', '相框玻璃是普通的还是高清的', '亲，这款相框玻璃是高清透明玻璃的，不是亚克力~高清玻璃透光好不反光，照片看得清楚。比亚克力贵但质感好，亚克力容易刮花发雾。用了大半年玻璃没有划痕，成色很新，换了大相框才出，价格很实惠。发货玻璃我会包好防碎，碎了包赔您放心。如果您要亚克力款我也有，更轻便不怕碎~', '相框,玻璃,高清,亚克力', '相框玻璃材质说明', 82
  UNION ALL SELECT 'home_decor', '这个树脂摆件会变色吗？晒了会褪色吗', '亲，树脂摆件长期暴晒会轻微变色，但正常室内摆放不会~建议不要放阳光直射的窗台，放书架电视柜这种散光位置就没问题。我这款用了大半年在室内没变色，成色很新。树脂比石膏耐潮比陶瓷耐摔，是性价比很高的摆件材质。换风格才出，价格很实惠，您看中了就拍下~', '树脂,摆件,变色,褪色', '树脂摆件变色说明', 81
  UNION ALL SELECT 'home_decor', '花瓶打包会碎吗？怎么包装', '亲，花瓶是易碎品我会包得很严实~先用气泡膜裹3-4层，再放进泡沫箱卡紧，外面再加纸箱，基本不会碎。万一碎了您拍照给我，我全额赔偿或者补发，您不用担心。用了大半年成色很新没有裂纹，换风格才出，价格很实惠。陶瓷的东西我发得多了，包装经验丰富，您放心拍下~', '花瓶,打包,易碎,包装', '花瓶包装与理赔说明', 87
  UNION ALL SELECT 'home_decor', '挂画装裱了吗？还是要自己装框', '亲，这款挂画是已经装裱好的，带实木画框，收到就能挂~不用自己再花钱装框，省事省钱。画框背面有挂钩和挂绳，挂墙上一颗钉子就行。用了大半年成色很新，换风格才出，价格比单买画芯加装框便宜不少。您看中了就拍下，收到直接挂上就行，很方便~', '挂画,装裱,画框,挂绳', '挂画装裱与安装说明', 84
  UNION ALL SELECT 'home_decor', '香薰有几种味道？能选吗', '亲，这款香薰有白茶、檀香、玫瑰、薰衣草、柑橘5种味道可以选~白茶清淡优雅适合卧室，檀香沉稳适合书房，玫瑰浪漫适合客厅，薰衣草助眠适合卧室，柑橘清新适合客厅。您拍的时候告诉我选哪种味道就行。用了几次成色很新（白茶味），朋友送了新的才出，价格比专柜便宜不少~', '香薰,味道,选择,香型', '香薰味道种类与选择', 84
  UNION ALL SELECT 'home_decor', '摆件有多重？放车上摆件会不会倒', '亲，这款摆件大概500g，有一定分量~底部平整有防滑毛毡垫，放桌面不会滑。放车上的话不建议，车颠簸急刹容易倒。如果要放车饰建议选底部重的或者带防滑垫的。这款适合放家里书架电视柜，稳定不会倒。用了大半年成色很新，换风格才出，价格很实惠，您看中了就拍下~', '摆件,重量,车上,防滑', '摆件重量与稳定性说明', 80
  UNION ALL SELECT 'home_decor', '相框支持多大尺寸照片？能定制吗', '亲，这款相框是5寸的，能放5寸（12.7×8.9cm）照片~我店里还有6寸、7寸、A4等尺寸的，您需要多大告诉我。定制尺寸也可以，但要加钱且周期长，建议选现成的。用了大半年成色很新，换了大相框才出，价格很实惠。您看中了就拍下，告诉我要多大尺寸的就行~', '相框,尺寸,照片,定制', '相框尺寸与定制说明', 81
  UNION ALL SELECT 'home_decor', '这个摆件是品牌吗？有包装盒吗', '亲，这款摆件不是大牌，是原创设计师工作室的~没有品牌包装盒，但有普通纸盒包装发货。原创设计的好处是造型独特不会撞款，比流水线摆件有特色。树脂材质做工精细，没有毛边瑕疵。用了大半年成色很新，换风格才出，价格比大牌便宜很多，性价比高。您看中了就拍下，自用或者送人都合适~', '摆件,品牌,包装,原创', '摆件品牌与包装说明', 82
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;


-- ============================================================================
-- 5. home_storage（收纳整理）- 30 条
-- ============================================================================
INSERT IGNORE INTO ai_cs_learned_kb (
    category_id, question, answer, tags, source_summary,
    content_hash, score, review_status, enabled, vector_indexed,
    source_count, source_conv_ids, learn_batch_id, sensitive_filtered,
    source_type, deleted, created_time, updated_time
)
SELECT c.id, q.question, q.answer, q.tags, q.source_summary,
       MD5(CONCAT(q.question, q.answer)), q.score, 'approved', 1, 1,
       1, NULL, 'seed-v1.54', 1, 'seed', 0, NOW(), NOW()
FROM (
  SELECT 'home_storage' AS code, '收纳箱能折叠吗？不用了省空间' AS question, '亲，这款收纳箱是可以折叠的，不用的时候折叠起来只有5cm厚，很省空间~展开就是正常收纳箱，容量50L，能装不少衣服被褥。材质是加厚PP的，结实不软塌，叠放3-4个没问题。带盖防尘，侧面有提手方便搬动。用了大半年成色很新，换了大柜子才出，价格很实惠，您看中了就拍下~' AS answer, '收纳箱,折叠,省空间,PP' AS tags, '收纳箱折叠与省空间说明' AS source_summary, 86 AS score
  UNION ALL SELECT 'home_storage', '置物架承重多少？放重物会弯吗', '亲，这款置物架每层承重15kg，放重物不会弯~层板是加厚铁板的，不是薄铁皮，承重力强。我放了满层书都没变形。架身是碳钢喷塑的，防锈耐用。4层设计收纳量大。如果有特别重的东西建议分散放，不要一层堆太重。用了大半年成色很新，换了大架子才出，价格很实惠~', '置物架,承重,铁板,碳钢', '置物架承重与材质说明', 85
  UNION ALL SELECT 'home_storage', '衣架是防滑的吗？衣服会掉吗', '亲，这款衣架是防滑的，肩部有防滑胶条，衣服不会掉~挂丝绸滑面料的也不滑，这个设计很实用。而且是宽肩设计，挂大衣外套不会鼓包变形。植绒材质透气不伤衣服。一套20个，够用。用了大半年成色很新，换风格才出，价格很实惠。这种防滑宽肩衣架市面上不便宜，您看中了就拍下~', '衣架,防滑,宽肩,植绒', '衣架防滑与防掉说明', 84
  UNION ALL SELECT 'home_storage', '挂钩承重怎么样？粘的牢吗', '亲，这款免钉挂钩承重3kg，粘得很牢~用的是强力无痕胶，粘瓷砖玻璃木板都行。我挂了浴球和毛巾半年没掉过。但要注意：粘之前把墙面擦干净擦干，粘上后等24小时再挂东西，这样最牢。不要挂超过3kg的重物。用了大半年成色很新，搬家才出，价格很实惠。撕下来不留痕，租房也放心~', '挂钩,承重,免钉,无痕胶', '挂钩承重与粘性说明', 83
  UNION ALL SELECT 'home_storage', '收纳箱多大容量？能装几件衣服', '亲，这款收纳箱容量50L，大概能装15-20件秋冬衣服或者一床薄被~如果是夏装能装更多。尺寸50×40×30cm，放衣柜下层或者床底都合适。带盖防尘，叠放省空间。用了大半年成色很新，换了大柜子才出，价格很实惠。您根据自家收纳空间选尺寸就行，我店里有不同大小可以挑~', '收纳箱,容量,衣服,尺寸', '收纳箱容量与装载说明', 82
  UNION ALL SELECT 'home_storage', '置物架需要打孔吗？免打孔牢固吗', '亲，这款置物架是免打孔的，用吸盘或者免钉胶固定~免打孔的好处是不破坏墙面，租房也能用。牢固性方面，吸盘款适合瓷砖光滑墙面，免钉胶款更牢适合各种墙面。免钉胶粘上等24小时再放东西，承重和打孔的差不多。用了大半年成色很新，搬家才出，价格很实惠。您家是什么墙面我帮您推荐合适的款~', '置物架,免打孔,吸盘,免钉胶', '置物架免打孔与固定说明', 84
  UNION ALL SELECT 'home_storage', '这个收纳盒是塑料的还是无纺布的', '亲，这款收纳盒是加厚PP塑料的，比无纺布结实~塑料的好处是防水防潮，能擦洗，放卫生间厨房也行。无纺布的怕水不能擦，但透气。各有优缺点。这款PP塑料的硬度高不软塌，叠放稳固。用了大半年成色很新，换了大柜子才出，价格很实惠。您要根据收纳场景选材质，潮湿环境选塑料~', '收纳盒,塑料,无纺布,PP', '收纳盒材质对比说明', 82
  UNION ALL SELECT 'home_storage', '衣架多少个一起出？够用吗', '亲，这款衣架一套20个出，一般家庭够用~如果衣服多可以多拍几套，有优惠。20个能挂一排大衣或者外套。衣架是植绒防滑宽肩的，质量不错。用了大半年成色很新，换风格才出，价格很实惠。这种质量的衣架超市一个就好几块，我这20个很划算，您看中了就拍下~', '衣架,数量,套装,够用', '衣架数量与套装说明', 81
  UNION ALL SELECT 'home_storage', '挂钩是免钉的吗？租房能用吗', '亲，这款挂钩是免钉的，用无痕胶粘，租房完全能用~撕下来不留胶痕不伤墙，退租也不怕。粘的时候墙面擦干净，按紧等24小时再用就行。一套6个，承重3kg每个。用了大半年成色很新，搬家才出，价格很实惠。租房族必备，挂毛巾挂钥匙挂小物件都方便，您看中了就拍下~', '挂钩,免钉,租房,无痕', '挂钩免钉与租房适用', 85
  UNION ALL SELECT 'home_storage', '收纳箱带轮子吗？推着方便吗', '亲，这款收纳箱带轮子的，底下4个万向轮，推着很方便~轮子有刹车，停下踩一下就锁住不会乱滑。带轮的好处是装满重物也能轻松推着走，放衣柜下面拉取方便。轮子是静音的，推起来不吵。用了大半年成色很新，换了大柜子才出，价格很实惠。您看中了就拍下，带轮的比不带的好用很多~', '收纳箱,轮子,万向轮,刹车', '收纳箱带轮与便利说明', 84
  UNION ALL SELECT 'home_storage', '置物架几层？高度能调节吗', '亲，这款置物架是4层的，层板高度可以调节~每层有多个卡位，按物品高度自由调节，大件小件都能放。展开尺寸60×30×120cm，放厨房放卫生间放书房都行。碳钢喷塑防锈耐用。用了大半年成色很新，换了大架子才出，价格很实惠。可调节层板很实用，您看中了就拍下~', '置物架,层数,调节,高度', '置物架层数与调节说明', 83
  UNION ALL SELECT 'home_storage', '收纳柜有抽屉吗？抽拉顺滑吗', '亲，这款收纳柜是3层抽屉的，抽拉很顺滑~用的是滚珠滑轨，比普通滑轨顺滑耐用，不卡顿。每个抽屉深度15cm，能放内衣袜子杂物。柜子是PP塑料的，防水防潮，放卧室卫生间都行。用了大半年成色很新，换了大柜子才出，价格很实惠。抽屉式比翻盖的好拿取，您看中了就拍下~', '收纳柜,抽屉,滑轨,顺滑', '收纳柜抽屉与滑轨说明', 83
  UNION ALL SELECT 'home_storage', '这个真空压缩袋漏气吗？能反复用吗', '亲，这款真空压缩袋不漏气，能反复用~用的是加厚PA+PE材质，比普通压缩袋厚不容易破。密封条是双道的，气密性好。抽气阀也密封严实。我反复用了3-4次还很好。用来收纳被子羽绒服很省空间，抽完能压缩到原来1/3。用了大半年成色很新，换了大柜子才出，价格很实惠~', '压缩袋,漏气,反复用,真空', '压缩袋气密与反复使用', 85
  UNION ALL SELECT 'home_storage', '衣架是植绒的还是塑料的？哪个好', '亲，这款衣架是植绒的，就是塑料衣架表面植绒~植绒的好处是防滑不伤衣服，挂丝绸也不滑也不起包。纯塑料衣架便宜但容易滑衣服。植绒的稍贵但好用很多。这款是宽肩防滑植绒的，挂大衣外套不会鼓包。用了大半年成色很新，换风格才出，价格很实惠，您看中了就拍下~', '衣架,植绒,塑料,防滑', '衣架植绒与塑料对比', 82
  UNION ALL SELECT 'home_storage', '挂钩防水吗？卫生间能用吗', '亲，这款挂钩是防水的，卫生间完全能用~无痕胶不怕水不怕潮，粘在浴室瓷砖上半年都没掉。但安装的时候墙面必须干透再粘，粘上等24小时再碰水，这样最牢。用了大半年成色很新，搬家才出，价格很实惠。挂浴球挂搓澡巾挂毛巾都方便，卫生间必备，您看中了就拍下~', '挂钩,防水,卫生间,瓷砖', '挂钩防水与卫生间适用', 83
  UNION ALL SELECT 'home_storage', '收纳箱透明吗？能看见里面吗', '亲，这款收纳箱是半透明的，能隐约看见里面装什么~不是全透明也不是全不透明，半透明的好处是不显得乱又能大致看到里面。找东西不用一个个翻。如果您要全透明或者全不透明的，我店里有别的款可以选。用了大半年成色很新，换了大柜子才出，价格很实惠~', '收纳箱,透明,半透明,可视', '收纳箱透明度说明', 80
  UNION ALL SELECT 'home_storage', '置物架是铁的还是塑料的？结实吗', '亲，这款置物架是碳钢喷塑的，比塑料结实很多~碳钢承重力强，每层15kg没问题，放满书都不弯。喷塑处理防锈耐用，厨房卫生间潮湿环境也能用。塑料架子轻但承重差容易老化。这款用了大半年没有锈迹变形，成色很新，换了大架子才出，价格很实惠，您看中了就拍下~', '置物架,铁,碳钢,结实', '置物架材质与结实度', 84
  UNION ALL SELECT 'home_storage', '这个收纳袋能装被子吗？容量大吗', '亲，这款收纳袋是加大号的，能装一床双人被~尺寸60×50×30cm，容量90L。材质是加厚无纺布的，透气不闷，被子放里面不会发霉。带提手方便搬动，拉链密封防尘。如果是厚冬被建议选更大的款，我帮您推荐。用了大半年成色很新，换了大柜子才出，价格很实惠~', '收纳袋,被子,容量,无纺布', '收纳袋容量与装被说明', 82
  UNION ALL SELECT 'home_storage', '衣架厚实吗？挂大衣会变形吗', '亲，这款衣架是加厚植绒的，挂大衣不会变形~衣架厚度3mm，比普通衣架厚实，承重一件厚大衣没问题。而且是宽肩设计，挂大衣外套肩部不会鼓包。植绒防滑，衣服不会滑落。用了大半年挂大衣外套没有变形，成色很新，换风格才出，价格很实惠。您看中了就拍下，厚衣架才能挂大衣~', '衣架,厚实,大衣,变形', '衣架厚度与挂大衣说明', 83
  UNION ALL SELECT 'home_storage', '挂钩一套几个？性价比怎么样', '亲，这款挂钩一套6个，性价比很高~免钉无痕胶的，租房也能用。超市一个免钉挂钩就要好几块，我这套6个很划算。承重3kg每个，挂毛巾浴球小物件都够。用了大半年成色很新，搬家才出。您如果需要多拍几套有优惠，厨房卫生间卧室都用得上，您看中了就拍下~', '挂钩,一套,数量,性价比', '挂钩套件与性价比说明', 81
  UNION ALL SELECT 'home_storage', '收纳箱盖子密封吗？防尘防潮吗', '亲，这款收纳箱盖子是密封的，防尘防潮效果好~盖子和箱体是凹凸扣合的，缝隙小，灰尘湿气进不去。放衣服被褥不用怕受潮发霉。如果是放潮湿环境，建议选带密封圈的款更好。这款用了大半年成色很新，盖子密封还很好，换了大柜子才出，价格很实惠。您看中了就拍下~', '收纳箱,盖子,密封,防潮', '收纳箱盖子密封说明', 83
  UNION ALL SELECT 'home_storage', '置物架组装简单吗？女生能装吗', '亲，这款置物架组装很简单，女生一个人就能装~不用螺丝刀，用的是卡扣设计，层板和立柱一卡就行。说明书图文并茂，10分钟就能装好。而且可以自由调节层数和高度，很灵活。用了大半年成色很新，搬家才出，价格很实惠。女生租房必备，不用工具自己就能装，您看中了就拍下~', '置物架,组装,简单,卡扣', '置物架组装与便利说明', 85
  UNION ALL SELECT 'home_storage', '这个分隔收纳盒适合放抽屉吗？尺寸多少', '亲，这款分隔收纳盒是专为抽屉设计的，尺寸32×22×6cm~适合标准抽屉，放内衣袜子领带很整齐。分隔板可以拆卸调节，按物品大小自由组合。材质是PP塑料的，好擦洗。用了大半年成色很新，换了大柜子才出，价格很实惠。您量下自家抽屉尺寸再拍，放抽屉里东西整齐好找，您看中了就拍下~', '收纳盒,分隔,抽屉,尺寸', '分隔收纳盒与抽屉适用', 83
  UNION ALL SELECT 'home_storage', '衣架会不会掉漆？用久了变色吗', '亲，这款衣架是植绒的不掉漆~植绒衣架表面是绒毛不是油漆，不存在掉漆问题。用久了绒毛也不会掉，颜色不变。比喷漆衣架好，喷漆的用久了会掉漆弄脏衣服。这款植绒的用了大半年还跟新的一样，成色很新，换风格才出，价格很实惠。您看中了就拍下，植绒衣架不掉漆不伤衣服~', '衣架,掉漆,植绒,变色', '衣架掉漆与变色说明', 82
  UNION ALL SELECT 'home_storage', '挂钩能挂在瓷砖上吗？留痕吗', '亲，这款挂钩能挂在瓷砖上，撕下来不留痕~用的是无痕胶，粘瓷砖玻璃光滑墙面都很牢。撕的时候慢慢扯，不会留胶痕也不会破坏瓷砖。但粗糙墙面比如刷漆墙效果差一些，建议选免钉胶款。用了大半年挂瓷砖上没掉过，成色很新，搬家才出，价格很实惠。您家什么墙面告诉我，我帮您推荐~', '挂钩,瓷砖,留痕,无痕胶', '挂钩瓷砖适用与留痕', 84
  UNION ALL SELECT 'home_storage', '收纳箱能叠放吗？摞起来稳吗', '亲，这款收纳箱可以叠放的，摞3-4个很稳~箱盖和箱底有凹凸卡扣设计，叠放时卡住不会滑落。材质是加厚PP的，承重够，叠放不会压塌。这样竖向收纳省地面空间。用了大半年成色很新，换了大柜子才出，价格很实惠。叠放收纳是小户型省空间的利器，您看中了就拍下~', '收纳箱,叠放,卡扣,稳固', '收纳箱叠放与稳固说明', 84
  UNION ALL SELECT 'home_storage', '置物架防锈吗？厨房能用吗', '亲，这款置物架是碳钢喷塑的，防锈，厨房完全能用~喷塑处理就是在铁表面喷一层塑粉高温烤，比喷漆防锈好很多。厨房油烟潮湿环境也不容易生锈。日常擦干水渍就行。用了大半年放厨房没有锈迹，成色很新，换了大架子才出，价格很实惠。厨房收纳架选喷塑碳钢的准没错~', '置物架,防锈,厨房,喷塑', '置物架防锈与厨房适用', 85
  UNION ALL SELECT 'home_storage', '这个裤架能挂几条裤子？滑顺吗', '亲，这款裤架能挂5条裤子，滑轨很顺滑~S型挂钩设计，取裤子不用整条抽出来，很方便。滑轨是静音滚珠的，拉取顺滑不卡。挂西装裤牛仔裤都行，不会皱。用了大半年成色很新，换了大衣柜才出，价格很实惠。裤架是衣柜收纳神器，挂起来比叠着好找，您看中了就拍下~', '裤架,挂裤,滑轨,顺滑', '裤架容量与滑轨说明', 83
  UNION ALL SELECT 'home_storage', '收纳箱是 PP 材质吗？食品级吗', '亲，这款收纳箱是PP材质的，但不是食品级，建议不要直接放食物~PP是食品级塑料的一种，但这款没有食品级认证，放衣物杂物没问题。如果要放食物建议选有食品级认证的。放厨房调料干货（带包装）是可以的。用了大半年成色很新，换了大柜子才出，价格很实惠。您如果是放食物我可以给您推荐食品级的款~', '收纳箱,PP,食品级,材质', '收纳箱PP材质与食品级', 82
  UNION ALL SELECT 'home_storage', '挂钩承重 5kg 真的吗？挂重物掉吗', '亲，这款挂钩标称承重3kg，实测挂3kg以内的很稳~不建议挂超过3kg的重物，时间长可能会掉。挂浴球毛巾没问题，挂锅具就不行。如果您要挂重物建议选打孔款的更牢。免钉挂钩的承重和墙面、安装方式都有关系，按说明安装最牢。用了大半年成色很新，搬家才出，价格很实惠~', '挂钩,承重,3kg,重物', '挂钩承重与使用限制', 81
) q
JOIN ai_cs_kb_category c ON c.code = q.code AND c.deleted = 0 AND c.parent_id IS NOT NULL;
